/* ===== 纯函数区（第一个无属性 script）：可被 Node _test.js 提取并断言 ===== */
var B64C='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
function strToBytes(s){ return new TextEncoder().encode(s); }
function bytesToStr(b){ return new TextDecoder().decode(b); }
function bytesToB64(bytes){
  var out='', i;
  for(i=0;i+2<bytes.length;i+=3){
    var n=(bytes[i]<<16)|(bytes[i+1]<<8)|bytes[i+2];
    out+=B64C[(n>>18)&63]+B64C[(n>>12)&63]+B64C[(n>>6)&63]+B64C[n&63];
  }
  var rem=bytes.length-i;
  if(rem===1){ var n1=bytes[i]<<16; out+=B64C[(n1>>18)&63]+B64C[(n1>>12)&63]+'=='; }
  else if(rem===2){ var n2=(bytes[i]<<16)|(bytes[i+1]<<8); out+=B64C[(n2>>18)&63]+B64C[(n2>>12)&63]+B64C[(n2>>6)&63]+'='; }
  return out;
}
function b64ToBytes(s){
  s=String(s).replace(/\s+/g,'').replace(/=+$/,'');
  var out=[], i;
  for(i=0;i+3<s.length;i+=4){
    var n=(B64C.indexOf(s[i])<<18)|(B64C.indexOf(s[i+1])<<12)|(B64C.indexOf(s[i+2])<<6)|B64C.indexOf(s[i+3]);
    out.push((n>>16)&255,(n>>8)&255,n&255);
  }
  var rem=s.length-i;
  if(rem===2){ var n3=(B64C.indexOf(s[i])<<18)|(B64C.indexOf(s[i+1])<<12); out.push((n3>>16)&255); }
  else if(rem===3){ var n4=(B64C.indexOf(s[i])<<18)|(B64C.indexOf(s[i+1])<<12)|(B64C.indexOf(s[i+2])<<6); out.push((n4>>16)&255,(n4>>8)&255); }
  return Uint8Array.from(out);
}
function randomBytes(n){
  var b=new Uint8Array(n);
  if(typeof globalThis!=='undefined' && globalThis.crypto && globalThis.crypto.getRandomValues) globalThis.crypto.getRandomValues(b);
  else for(var i=0;i<n;i++) b[i]=Math.floor(Math.random()*256);
  return b;
}
function formatPackage(salt, iv, ct){
  return 'v1|'+bytesToB64(salt)+'|'+bytesToB64(iv)+'|'+bytesToB64(ct);
}
function parsePackage(pkg){
  var p=String(pkg).split('|');
  if(p.length!==4 || p[0]!=='v1') return null;
  try{ return { salt:b64ToBytes(p[1]), iv:b64ToBytes(p[2]), ct:b64ToBytes(p[3]) }; }
  catch(e){ return null; }
}
async function deriveKey(passphrase, salt){
  var baseKey=await globalThis.crypto.subtle.importKey('raw', strToBytes(passphrase), 'PBKDF2', false, ['deriveKey']);
  return globalThis.crypto.subtle.deriveKey(
    {name:'PBKDF2', salt:salt, iterations:100000, hash:'SHA-256'},
    baseKey, {name:'AES-GCM', length:256}, false, ['encrypt','decrypt']);
}
async function encrypt(plaintext, passphrase){
  var salt=randomBytes(16), iv=randomBytes(12);
  var key=await deriveKey(passphrase, salt);
  var ct=await globalThis.crypto.subtle.encrypt({name:'AES-GCM', iv:iv}, key, strToBytes(plaintext));
  return formatPackage(salt, iv, new Uint8Array(ct));
}
async function decrypt(pkg, passphrase){
  var parts=parsePackage(pkg);
  if(!parts) throw new Error('密文格式无法识别');
  var key=await deriveKey(passphrase, parts.salt);
  var pt=await globalThis.crypto.subtle.decrypt({name:'AES-GCM', iv:parts.iv}, key, parts.ct);
  return bytesToStr(new Uint8Array(pt));
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { strToBytes:strToBytes, bytesToStr:bytesToStr, bytesToB64:bytesToB64, b64ToBytes:b64ToBytes,
    randomBytes:randomBytes, formatPackage:formatPackage, parsePackage:parsePackage, deriveKey:deriveKey, encrypt:encrypt, decrypt:decrypt };
}
if (typeof window !== 'undefined') {
  window.CryptoForgePure = { strToBytes:strToBytes, bytesToStr:bytesToStr, bytesToB64:bytesToB64, b64ToBytes:b64ToBytes,
    randomBytes:randomBytes, formatPackage:formatPackage, parsePackage:parsePackage, deriveKey:deriveKey, encrypt:encrypt, decrypt:decrypt };
}
